export class MatrixError extends Error {
  constructor(
    message: string,
    public status: number,
    public code?: string,
  ) {
    super(message);
    this.name = 'MatrixError';
  }
}

export class ModuleNotSubscribedError extends MatrixError {
  constructor() {
    super('Module not subscribed', 403, 'MODULE_NOT_SUBSCRIBED');
    this.name = 'ModuleNotSubscribedError';
  }
}

export class InsufficientTokensError extends MatrixError {
  constructor() {
    super('Insufficient token balance', 402, 'INSUFFICIENT_TOKENS');
    this.name = 'InsufficientTokensError';
  }
}

import type {
  LeadPayload,
  MatrixContext,
  NotifyPayload,
  ProviderConnectionResponse,
  TokenConsumePayload,
} from '@busymanager/api-contracts';
import {
  InsufficientTokensError,
  MatrixError,
  ModuleNotSubscribedError,
} from './errors.js';

export interface MatrixClientOptions {
  baseUrl: string;
  moduleKey: string;
  fetchImpl?: typeof fetch;
}

export function createMatrixClient(options: MatrixClientOptions) {
  const baseUrl = options.baseUrl.replace(/\/$/, '');
  const fetchFn = options.fetchImpl ?? fetch;

  async function request<T>(
    method: string,
    path: string,
    body?: unknown,
  ): Promise<T> {
    const res = await fetchFn(`${baseUrl}/api/v1/matrix${path}`, {
      method,
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
        'X-Module-Key': options.moduleKey,
      },
      body: body !== undefined ? JSON.stringify(body) : undefined,
    });

    if (!res.ok) {
      const data = (await res.json().catch(() => ({}))) as { message?: string };
      if (res.status === 403 && path.includes('subscriptions')) {
        throw new ModuleNotSubscribedError();
      }
      if (res.status === 402) {
        throw new InsufficientTokensError();
      }
      throw new MatrixError(data.message ?? res.statusText, res.status);
    }

    return res.json() as Promise<T>;
  }

  return {
    auth: {
      check: () => request<MatrixContext>('GET', '/auth/check'),
    },
    subscriptions: {
      check: async (slug: string) => {
        const res = await request<{ active: boolean }>(
          'GET',
          `/subscriptions/check/${slug}`,
        );
        return res.active;
      },
    },
    connections: {
      get: (provider: string) =>
        request<ProviderConnectionResponse>('GET', `/connections/${provider}`),
      list: () =>
        request<{ connections: unknown[] }>('GET', '/connections'),
    },
    tokens: {
      check: async (amount: number) => {
        const res = await request<{ sufficient: boolean }>(
          'POST',
          '/tokens/check',
          { amount },
        );
        if (!res.sufficient) throw new InsufficientTokensError();
        return res;
      },
      consume: (payload: TokenConsumePayload) =>
        request<{ balance: number }>('POST', '/tokens/consume', payload),
    },
    leads: {
      create: (data: LeadPayload) => request<unknown>('POST', '/leads', data),
      update: (id: number, data: Partial<LeadPayload>) =>
        request<unknown>('PATCH', `/leads/${id}`, data),
      event: (id: number, type: string, data?: Record<string, unknown>) =>
        request<unknown>('POST', `/leads/${id}/events`, { type, data }),
    },
    webhooks: {
      emit: (event: string, data: Record<string, unknown>) =>
        request<{ dispatched: number }>('POST', '/webhooks/emit', {
          event,
          data,
        }),
    },
    notify: (channel: string, msg: Omit<NotifyPayload, 'channel'>) =>
      request<unknown>('POST', '/notify', { channel, ...msg }),
  };
}

export type MatrixClient = ReturnType<typeof createMatrixClient>;

export { createMatrixClient, type MatrixClient, type MatrixClientOptions } from './client.js';
export {
  MatrixError,
  ModuleNotSubscribedError,
  InsufficientTokensError,
} from './errors.js';

import { describe, expect, it, vi } from 'vitest';
import { createMatrixClient } from './client.js';
import { InsufficientTokensError, ModuleNotSubscribedError } from './errors.js';

describe('createMatrixClient', () => {
  it('checks subscription', async () => {
    const fetchImpl = vi.fn().mockResolvedValue({
      ok: true,
      json: async () => ({ active: true }),
    });

    const matrix = createMatrixClient({
      baseUrl: 'http://localhost:8080',
      moduleKey: 'bm_test',
      fetchImpl,
    });

    const active = await matrix.subscriptions.check('web-uptime');
    expect(active).toBe(true);
    expect(fetchImpl).toHaveBeenCalledWith(
      'http://localhost:8080/api/v1/matrix/subscriptions/check/web-uptime',
      expect.objectContaining({
        headers: expect.objectContaining({ 'X-Module-Key': 'bm_test' }),
      }),
    );
  });

  it('throws ModuleNotSubscribedError on 403', async () => {
    const fetchImpl = vi.fn().mockResolvedValue({
      ok: false,
      status: 403,
      statusText: 'Forbidden',
      json: async () => ({ message: 'not subscribed' }),
    });

    const matrix = createMatrixClient({
      baseUrl: 'http://localhost:8080',
      moduleKey: 'bm_test',
      fetchImpl,
    });

    await expect(matrix.subscriptions.check('seo-onpage')).rejects.toBeInstanceOf(
      ModuleNotSubscribedError,
    );
  });

  it('throws InsufficientTokensError on 402', async () => {
    const fetchImpl = vi.fn().mockResolvedValue({
      ok: false,
      status: 402,
      statusText: 'Payment Required',
      json: async () => ({}),
    });

    const matrix = createMatrixClient({
      baseUrl: 'http://localhost:8080',
      moduleKey: 'bm_test',
      fetchImpl,
    });

    await expect(matrix.tokens.check(500)).rejects.toBeInstanceOf(
      InsufficientTokensError,
    );
  });
});

