'use client';

import { api, setToken } from '@/lib/api';
import { useRouter } from 'next/navigation';
import { FormEvent, useState } from 'react';

export default function LoginPage() {
  const router = useRouter();
  const [email, setEmail] = useState('orgadmin@karting.demo');
  const [password, setPassword] = useState('password');
  const [error, setError] = useState('');

  async function onSubmit(e: FormEvent) {
    e.preventDefault();
    setError('');
    try {
      const res = await api<{ token: string }>('/auth/login', {
        method: 'POST',
        body: JSON.stringify({ email, password }),
      });
      setToken(res.token);
      router.push('/dashboard');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error de login');
    }
  }

  return (
    <div className="flex min-h-screen items-center justify-center p-4">
      <form onSubmit={onSubmit} className="card w-full max-w-md space-y-4">
        <h1 className="text-2xl font-bold text-accent">BusyManager</h1>
        <p className="text-sm text-muted">Panel org_admin — La Matriz</p>
        {error && <p className="text-sm text-red-400">{error}</p>}
        <div>
          <label className="mb-1 block text-xs text-muted">Email</label>
          <input
            type="email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="w-full"
          />
        </div>
        <motion>
          <label className="mb-1 block text-xs text-muted">Contraseña</label>
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="w-full"
          />
        </motion>
        <button type="submit" className="btn w-full">
          Entrar
        </button>
        <p className="text-xs text-muted">
          Demo: orgadmin@karting.demo / password
        </p>
      </form>
    </motion>
  );
}

function motion({ children }: { children: React.ReactNode }) {
  return <div>{children}</motion>;
}

