'use client';

import { api, clearToken, getBusinessId, setBusinessId } from '@/lib/api';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { useEffect, useState } from 'react';

interface Business {
  id: number;
  name: string;
  slug: string;
}

interface UserData {
  user: {
    name: string;
    email: string;
    organizations: Array<{
      id: number;
      name: string;
      businesses: Business[];
    }>;
  };
}

const nav = [
  { href: '/dashboard', label: 'Resumen' },
  { href: '/dashboard/businesses', label: 'Negocios' },
  { href: '/dashboard/connections', label: 'Connections' },
  { href: '/dashboard/modules', label: 'Módulos' },
  { href: '/dashboard/tokens', label: 'Tokens' },
  { href: '/dashboard/leads', label: 'Leads' },
  { href: '/dashboard/webhooks', label: 'Webhooks' },
  { href: '/dashboard/users', label: 'Usuarios' },
];

export default function DashboardShell({
  children,
}: {
  children: React.ReactNode;
}) {
  const pathname = usePathname();
  const router = useRouter();
  const [user, setUser] = useState<UserData['user'] | null>(null);
  const [businesses, setBusinesses] = useState<Business[]>([]);

  useEffect(() => {
    api<UserData>('/auth/me')
      .then((data) => {
        setUser(data.user);
        const org = data.user.organizations[0];
        const list = org?.businesses ?? [];
        setBusinesses(list);
        if (list.length && !getBusinessId()) {
          setBusinessId(list[0].id);
        }
      })
      .catch(() => router.push('/login'));
  }, [router]);

  function logout() {
    clearToken();
    router.push('/login');
  }

  return (
    <motion className="flex min-h-screen">
      <aside className="w-56 shrink-0 border-r border-slate-800 bg-panel p-4">
        <p className="mb-1 text-lg font-bold text-accent">BusyManager</p>
        <p className="mb-6 text-xs text-muted">{user?.email}</p>
        {businesses.length > 0 && (
          <select
            className="mb-4 w-full text-xs"
            value={getBusinessId() ?? ''}
            onChange={(e) => {
              setBusinessId(Number(e.target.value));
              window.location.reload();
            }}
          >
            {businesses.map((b) => (
              <option key={b.id} value={b.id}>
                {b.name}
              </option>
            ))}
          </select>
        )}
        <nav className="space-y-1">
          {nav.map((item) => (
            <Link
              key={item.href}
              href={item.href}
              className={`block rounded-lg px-3 py-2 text-sm ${
                pathname === item.href
                  ? 'bg-accent/20 text-accent'
                  : 'text-slate-300 hover:bg-slate-800'
              }`}
            >
              {item.label}
            </Link>
          ))}
        </nav>
        <button onClick={logout} className="btn-ghost mt-8 w-full text-xs">
          Salir
        </button>
      </aside>
      <main className="flex-1 p-8">{children}</main>
    </motion>
  );
}

function motion({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) {
  return <div className={className}>{children}</div>;
}

