'use client';

import { api, clearToken, getBusinessId, setBusinessId } from '@/lib/api';
import {
  AppsSidebarResponse,
  CATEGORY_LABELS,
  SidebarApp,
} from '@/lib/modules';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { useCallback, useEffect, useState } from 'react';

interface Business {
  id: number;
  name: string;
  slug: string;
}

interface UserData {
  user: {
    name: string;
    email: string;
    organizations: Array<{
      id: number;
      name: string;
      businesses: Business[];
    }>;
  };
}

function AppNavItem({ app, businessId }: { app: SidebarApp; businessId: string }) {
  const pathname = usePathname();
  const href = `/dashboard/apps/${app.slug}`;
  const isActive = pathname === href || pathname.startsWith(`${href}/`);
  const isClickable = app.status === 'active';

  const base =
    'flex items-center gap-2.5 rounded-lg px-3 py-2 text-sm transition';
  const styles = {
    active: isActive
      ? 'bg-orange-50 font-medium text-orange-700'
      : 'text-slate-700 hover:bg-slate-50',
    inactive: 'text-slate-400 hover:bg-slate-50 hover:text-slate-600',
    coming_soon: 'cursor-not-allowed text-slate-300',
  }[app.status];

  const dot = {
    active: 'bg-emerald-500',
    inactive: 'border border-slate-300 bg-transparent',
    coming_soon: 'border border-dashed border-slate-300',
  }[app.status];

  const inner = (
    <>
      <span className={`h-2 w-2 shrink-0 rounded-full ${dot}`} />
      <span className="truncate">{app.name}</span>
      {app.status === 'coming_soon' && (
        <span className="ml-auto text-[10px] uppercase text-slate-400">Pronto</span>
      )}
    </>
  );

  if (!isClickable) {
    return (
      <Link href={href} className={`${base} ${styles}`} title="Ver detalle o activar">
        {inner}
      </Link>
    );
  }

  return (
    <Link href={href} className={`${base} ${styles}`}>
      {inner}
    </Link>
  );
}

export default function AppSidebar() {
  const pathname = usePathname();
  const router = useRouter();
  const [user, setUser] = useState<UserData['user'] | null>(null);
  const [businesses, setBusinesses] = useState<Business[]>([]);
  const [sidebar, setSidebar] = useState<AppsSidebarResponse | null>(null);
  const businessId = getBusinessId();

  const loadSidebar = useCallback(() => {
    if (!businessId) return;
    api<AppsSidebarResponse>(`/businesses/${businessId}/apps-sidebar`).then(setSidebar);
  }, [businessId]);

  useEffect(() => {
    api<UserData>('/auth/me').then((data) => {
      setUser(data.user);
      const list = data.user.organizations[0]?.businesses ?? [];
      setBusinesses(list);
      if (list.length && !getBusinessId()) setBusinessId(list[0].id);
    });
  }, []);

  useEffect(() => {
    loadSidebar();
  }, [loadSidebar, pathname]);

  const systemNav = [
    { href: '/dashboard', label: 'Inicio', icon: '◉' },
    { href: '/dashboard/leads', label: 'Leads', icon: '◎' },
  ];

  const bottomNav = [
    { href: '/dashboard/settings', label: 'Configuración' },
    { href: '/dashboard/integrations', label: 'Integraciones' },
    { href: '/dashboard/team', label: 'Equipo' },
    { href: '/dashboard/tokens', label: 'Tokens IA' },
  ];

  return (
    <aside className="flex h-screen w-64 shrink-0 flex-col border-r border-slate-200 bg-white">
      <motion className="border-b border-slate-100 px-4 py-5">
        <p className="text-lg font-semibold tracking-tight text-slate-900">BusyManager</p>
        <p className="mt-0.5 truncate text-xs text-slate-500">
          {user?.organizations[0]?.name ?? user?.email}
        </p>
        {businesses.length > 0 && (
          <select
            className="mt-3 text-xs"
            value={businessId ?? ''}
            onChange={(e) => {
              setBusinessId(Number(e.target.value));
              window.location.href = '/dashboard';
            }}
          >
            {businesses.map((b) => (
              <option key={b.id} value={b.id}>
                {b.name}
              </option>
            ))}
          </select>
        )}
      </motion>

