        <div className="mb-2 space-y-0.5">
          {systemNav.map((item) => (
            <Link
              key={item.href}
              href={item.href}
              className={`flex items-center gap-2 rounded-lg px-3 py-2 text-sm ${
                pathname === item.href
                  ? 'bg-slate-100 font-medium text-slate-900'
