'use client';

import { api, clearToken, getBusinessId, setBusinessId } from '@/lib/api';
import {
  AppsSidebarResponse,
  CATEGORY_LABELS,
  SidebarApp,
} from '@/lib/modules';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { useCallback, useEffect, useState } from 'react';

interface Business {
  id: number;
  name: string;
  slug: string;
}

interface UserData {
  user: {
    name: string;
    email: string;
    organizations: Array<{
      id: number;
      name: string;
      businesses: Business[];
    }>;
  };
}

function AppNavItem({ app }: { app: SidebarApp }) {
  const pathname = usePathname();
  const href = `/dashboard/apps/${app.slug}`;
  const isActive = pathname === href || pathname.startsWith(`${href}/`);

  const base =
    'flex items-center gap-2.5 rounded-lg px-3 py-2 text-sm transition';

  let styles = 'text-slate-600 hover:bg-slate-50';
  let dot = 'border border-slate-300 bg-transparent';

  if (app.status === 'active') {
    styles = isActive
      ? 'bg-orange-50 font-medium text-orange-700'
      : 'text-slate-700 hover:bg-slate-50';
    dot = 'bg-emerald-500';
  } else if (app.status === 'coming_soon') {
    styles = 'cursor-default text-slate-300';
    dot = 'border border-dashed border-slate-300';
  } else {
    styles = 'text-slate-400 hover:bg-slate-50 hover:text-slate-600';
  }

  if (app.status === 'coming_soon') {
    return (
      <motion className={`${base} ${styles}`} title="Próximamente">
        <span className={`h-2 w-2 shrink-0 rounded-full ${dot}`} />
        <span className="truncate">{app.name}</span>
        <span className="ml-auto text-[10px] uppercase">Pronto</span>
      </motion>
    );
  }

  return (
    <Link href={href} className={`${base} ${styles}`}>
      <span className={`h-2 w-2 shrink-0 rounded-full ${dot}`} />
      <span className="truncate">{app.name}</span>
    </Link>
  );
}

function Div({
  children,
  className,
  title,
}: {
  children: React.ReactNode;
  className?: string;
  title?: string;
}) {
  return (
    <motion className={className} title={title}>
      {children}
    </motion>
  );
}

export default function AppSidebar() {
  const pathname = usePathname();
  const router = useRouter();
  const [user, setUser] = useState<UserData['user'] | null>(null);
  const [businesses, setBusinesses] = useState<Business[]>([]);
  const [sidebar, setSidebar] = useState<AppsSidebarResponse | null>(null);
  const businessId = getBusinessId();

  const loadSidebar = useCallback(() => {
    if (!businessId) return;
    api<AppsSidebarResponse>(`/businesses/${businessId}/apps-sidebar`).then(setSidebar);
  }, [businessId]);

  useEffect(() => {
    api<UserData>('/auth/me').then((data) => {
      setUser(data.user);
      const list = data.user.organizations[0]?.businesses ?? [];
      setBusinesses(list);
      if (list.length && !getBusinessId()) setBusinessId(list[0].id);
    });
  }, []);

  useEffect(() => {
    loadSidebar();
  }, [loadSidebar, pathname]);

  const systemNav = [
    { href: '/dashboard', label: 'Inicio' },
    { href: '/dashboard/leads', label: 'Leads' },
  ];

  const bottomNav = [
    { href: '/dashboard/settings', label: 'Configuración' },
    { href: '/dashboard/integrations', label: 'Integraciones' },
    { href: '/dashboard/team', label: 'Equipo' },
    { href: '/dashboard/tokens', label: 'Tokens IA' },
  ];

  return (
    <aside className="flex h-screen w-64 shrink-0 flex-col border-r border-slate-200 bg-white">
      <div className="border-b border-slate-100 px-4 py-5">
        <p className="text-lg font-semibold tracking-tight text-slate-900">BusyManager</p>
        <p className="mt-0.5 truncate text-xs text-slate-500">
          {user?.organizations[0]?.name ?? user?.email}
        </p>
        {businesses.length > 0 && (
          <select
            className="mt-3 text-xs"
            value={businessId ?? ''}
            onChange={(e) => {
              setBusinessId(Number(e.target.value));
              window.location.href = '/dashboard';
            }}
          >
            {businesses.map((b) => (
              <option key={b.id} value={b.id}>
                {b.name}
              </option>
            ))}
          </select>
        )}
      </div>

      <nav className="flex-1 overflow-y-auto px-3 py-4">
        <div className="mb-2 space-y-0.5">
          {systemNav.map((item) => (
            <Link
              key={item.href}
              href={item.href}
              className={`block rounded-lg px-3 py-2 text-sm ${
                pathname === item.href
                  ? 'bg-slate-100 font-medium text-slate-900'
                  : 'text-slate-600 hover:bg-slate-50'
              }`}
            >
              {item.label}
            </Link>
          ))}
        </motion>

        {sidebar?.categories.map((cat) => (
          <div key={cat.id} className="mt-5">
            <p className="mb-1.5 px-3 text-[11px] font-semibold uppercase tracking-wider text-slate-400">
              {CATEGORY_LABELS[cat.id] ?? cat.id}
            </p>
            <div className="space-y-0.5">
              {cat.apps.map((app) => (
                <AppNavItem key={app.slug} app={app} />
              ))}
            </div>
          </div>
        ))}
      </nav>

      <div className="border-t border-slate-100 px-3 py-3">
        {bottomNav.map((item) => (
          <Link
            key={item.href}
            href={item.href}
            className={`block rounded-lg px-3 py-2 text-sm ${
              pathname === item.href || pathname.startsWith(item.href + '/')
                ? 'bg-orange-50 font-medium text-orange-700'
                : 'text-slate-600 hover:bg-slate-50'
            }`}
          >
            {item.label}
          </Link>
        ))}
        <button
          type="button"
          onClick={() => {
            clearToken();
            router.push('/login');
          }}
          className="mt-2 w-full rounded-lg px-3 py-2 text-left text-sm text-slate-500 hover:bg-slate-50"
        >
          Cerrar sesión
        </button>
      </div>
    </aside>
  );
}

