'use client';

import PageHeader from '@/components/PageHeader';
import { api, getBusinessId } from '@/lib/api';
import { BusinessSettings, EMPTY_SETTINGS } from '@/lib/settings';
import { FormEvent, useEffect, useState } from 'react';

export default function SettingsPage() {
  const businessId = getBusinessId();
  const [name, setName] = useState('');
  const [timezone, setTimezone] = useState('Europe/Madrid');
  const [settings, setSettings] = useState<BusinessSettings>(EMPTY_SETTINGS);
  const [saved, setSaved] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!businessId) return;
    api<{ name: string; timezone: string; settings: BusinessSettings }>(
      `/businesses/${businessId}/settings`,
    ).then((d) => {
      setName(d.name);
      setTimezone(d.timezone);
      setSettings({ ...EMPTY_SETTINGS, ...d.settings });
      setLoading(false);
    });
  }, [businessId]);

  async function onSubmit(e: FormEvent) {
    e.preventDefault();
    if (!businessId) return;
    await api(`/businesses/${businessId}/settings`, {
      method: 'PATCH',
      body: JSON.stringify({ name, timezone, settings }),
    });
    setSaved(true);
    setTimeout(() => setSaved(false), 3000);
  }

  function patchSection<K extends keyof BusinessSettings>(
    section: K,
    field: keyof BusinessSettings[K],
    value: string,
  ) {
    setSettings((s) => ({
      ...s,
      [section]: { ...s[section], [field]: value },
    }));
  }

  if (loading) {
    return <p className="text-sm text-slate-500">Cargando…</p>;
  }

  return (
    <div>
      <PageHeader
        title="Configuración"
        description="Datos compartidos por todas las apps de este negocio. Cada módulo los usa según necesite (web, fiscal, contacto…)."
      />

      <form onSubmit={onSubmit} className="max-w-3xl space-y-8">
        <section className="card">
          <h2 className="mb-4 text-base font-semibold text-slate-900">Negocio</h2>
          <motion className="grid gap-4 md:grid-cols-2">
            <div>
              <label className="label">Nombre del local</label>
              <input value={name} onChange={(e) => setName(e.target.value)} />
            </div>
            <div>
              <label className="label">Zona horaria</label>
              <input value={timezone} onChange={(e) => setTimezone(e.target.value)} />
            </div>
          </motion>
        </section>

        <section className="card">
          <h2 className="mb-4 text-base font-semibold text-slate-900">Identidad</h2>
          <div className="grid gap-4 md:grid-cols-2">
            <div>
              <label className="label">Nombre comercial</label>
              <input
                value={settings.identity.trade_name}
                onChange={(e) => patchSection('identity', 'trade_name', e.target.value)}
              />
            </div>
            <motion>
              <label className="label">Razón social</label>
              <input
                value={settings.identity.legal_name}
                onChange={(e) => patchSection('identity', 'legal_name', e.target.value)}
              />
            </motion>
            <div className="md:col-span-2">
              <label className="label">URL del logo</label>
              <input
                value={settings.identity.logo_url}
                onChange={(e) => patchSection('identity', 'logo_url', e.target.value)}
              />
            </motion>
          </div>
        </section>

        <section className="card">
          <h2 className="mb-4 text-base font-semibold text-slate-900">Web</h2>
          <div className="grid gap-4 md:grid-cols-2">
            <div className="md:col-span-2">
              <label className="label">URL de la web</label>
              <input
                type="url"
                placeholder="https://tu-negocio.com"
                value={settings.web.url}
                onChange={(e) => patchSection('web', 'url', e.target.value)}
              />
              <p className="mt-1 text-xs text-slate-400">
                Usada por Web caída, SEO, detector de enlaces, etc.
              </p>
            </div>
            <div>
              <label className="label">Idioma</label>
              <select
                value={settings.web.language}
                onChange={(e) => patchSection('web', 'language', e.target.value)}
              >
                <option value="es">Español</option>
                <option value="en">English</option>
              </select>
            </div>
          </div>
        </section>

        <section className="card">
          <h2 className="mb-4 text-base font-semibold text-slate-900">Datos fiscales</h2>
          <div className="grid gap-4 md:grid-cols-2">
            <div>
              <label className="label">CIF / NIF</label>
              <input
                value={settings.fiscal.tax_id}
                onChange={(e) => patchSection('fiscal', 'tax_id', e.target.value)}
              />
            </div>
            <div>
              <label className="label">Ciudad</label>
              <input
                value={settings.fiscal.city}
                onChange={(e) => patchSection('fiscal', 'city', e.target.value)}
              />
            </div>
            <div className="md:col-span-2">
              <label className="label">Dirección</label>
              <input
                value={settings.fiscal.address}
                onChange={(e) => patchSection('fiscal', 'address', e.target.value)}
              />
            </div>
            <div>
              <label className="label">Código postal</label>
              <input
                value={settings.fiscal.postal_code}
                onChange={(e) => patchSection('fiscal', 'postal_code', e.target.value)}
              />
            </div>
            <div>
              <label className="label">País</label>
              <input
                value={settings.fiscal.country}
                onChange={(e) => patchSection('fiscal', 'country', e.target.value)}
              />
            </div>
          </div>
        </section>

        <section className="card">
          <h2 className="mb-4 text-base font-semibold text-slate-900">Contacto público</h2>
          <div className="grid gap-4 md:grid-cols-2">
            <div>
              <label className="label">Teléfono</label>
              <input
                value={settings.contact.phone}
                onChange={(e) => patchSection('contact', 'phone', e.target.value)}
              />
            </div>
            <div>
              <label className="label">Email público</label>
              <input
                type="email"
                value={settings.contact.public_email}
                onChange={(e) => patchSection('contact', 'public_email', e.target.value)}
              />
            </div>
          </div>
        </section>

        <div className="flex items-center gap-3">
          <button type="submit" className="btn">
            Guardar configuración
          </button>
          {saved && <span className="text-sm text-emerald-600">Guardado correctamente</span>}
        </div>
      </form>
    </div>
  );
}

'use client';

import PageHeader from '@/components/PageHeader';
import { api, getBusinessId } from '@/lib/api';
import { AppsSidebarResponse, CATEGORY_LABELS } from '@/lib/modules';
import Link from 'next/link';
import { useParams } from 'next/navigation';
import { useEffect, useState } from 'react';

export default function AppPage() {
  const { slug } = useParams<{ slug: string }>();
  const businessId = getBusinessId();
  const [app, setApp] = useState<{
    name: string;
    status: string;
    description?: string | null;
  } | null>(null);
  const [apiKey, setApiKey] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!businessId || !slug) return;
    api<AppsSidebarResponse>(`/businesses/${businessId}/apps-sidebar`).then((data) => {
      for (const cat of data.categories) {
        const found = cat.apps.find((a) => a.slug === slug);
        if (found) {
          setApp({ name: found.name, status: found.status, description: found.description });
          break;
        }
      }
      setLoading(false);
    });
  }, [businessId, slug]);

  async function activate() {
    const res = await api<{ api_key: string }>(
      `/businesses/${businessId}/subscriptions/${slug}/activate`,
      { method: 'POST' },
    );
    setApiKey(res.api_key);
    setApp((a) => (a ? { ...a, status: 'active' } : a));
  }

  async function deactivate() {
    await api(`/businesses/${businessId}/subscriptions/${slug}`, { method: 'DELETE' });
    setApp((a) => (a ? { ...a, status: 'inactive' } : a));
    setApiKey(null);
  }

  if (loading) return <p className="text-sm text-slate-500">Cargando…</p>;
  if (!app) return <p className="text-sm text-red-600">App no encontrada</p>;

  const categoryLabel =
    Object.entries(CATEGORY_LABELS).find(([,]) => true)?.[1] ?? '';

  return (
    <div>
      <PageHeader
        title={app.name}
        description={
          app.description ??
          `Módulo ${slug}. ${app.status === 'active' ? 'Activa en este negocio.' : 'No activa.'}`
        }
        action={
          app.status === 'active' ? (
            <button type="button" className="btn-ghost" onClick={deactivate}>
              Desactivar
            </button>
          ) : app.status === 'inactive' ? (
            <button type="button" className="btn" onClick={activate}>
              Activar app
            </button>
          ) : null
        }
      />

      {app.status === 'coming_soon' && (
        <motion className="card border-dashed border-slate-200 bg-slate-50 text-center text-slate-500">
          Esta app estará disponible pronto.
        </motion>
      )}

      {app.status === 'inactive' && (
        <motion className="card">
          <p className="text-sm text-slate-600">
            Activa esta app para usarla en <strong>{categoryLabel || 'este negocio'}</strong>.
            Los datos de configuración (web, fiscal, contacto) se toman de{' '}
            <Link href="/dashboard/settings" className="text-orange-600 hover:underline">
              Configuración
            </Link>
            .
          </p>
        </motion>
      )}

      {app.status === 'active' && (
        <motion className="space-y-6">
          {apiKey && (
            <motion className="card border-orange-200 bg-orange-50">
              <p className="text-sm font-medium text-orange-900">API key del módulo</p>
              <code className="mt-2 block break-all text-xs text-orange-800">{apiKey}</code>
            </motion>
          )}

          <motion className="card">
            <h2 className="mb-2 font-semibold text-slate-900">Estado</h2>
            <p className="text-sm text-slate-600">
              <span className="inline-flex items-center gap-1.5 rounded-full bg-emerald-50 px-2.5 py-0.5 text-emerald-700">
                <span className="h-1.5 w-1.5 rounded-full bg-emerald-500" />
                Activa
              </span>
            </p>
            {slug === 'web-uptime' && (
              <p className="mt-4 text-sm text-slate-500">
                Configura la URL de tu web en{' '}
                <Link href="/dashboard/settings" className="text-orange-600 hover:underline">
                  Configuración → Web
                </Link>
                . El worker hará ping periódicamente y te avisará si cae.
              </p>
            )}
            {slug === 'lead-router' && (
              <p className="mt-4 text-sm text-slate-500">
                Los leads entrantes aparecen en{' '}
                <Link href="/dashboard/leads" className="text-orange-600 hover:underline">
                  Leads
                </Link>
                .
              </p>
            )}
          </motion>

          <motion className="card bg-slate-50">
            <p className="text-xs text-slate-500">
              Panel específico de la app en desarrollo. La lógica corre en el módulo alumno vía SDK.
            </p>
          </motion>
        </motion>
      )}
    </div>
  );
}

'use client';

import PageHeader from '@/components/PageHeader';
import { api } from '@/lib/api';
import { FormEvent, useEffect, useState } from 'react';

interface Connection {
  id: number;
  provider: string;
  scope: string;
  label: string;
}

export default function IntegrationsPage() {
  const [list, setList] = useState<Connection[]>([]);
  const [provider, setProvider] = useState('gemini');
  const [apiKey, setApiKey] = useState('');

  function load() {
    api<{ data: Connection[] }>('/org/connections').then((r) => setList(r.data));
  }

  useEffect(() => {
    load();
  }, []);

  async function create(e: FormEvent) {
    e.preventDefault();
    await api('/org/connections', {
      method: 'POST',
      body: JSON.stringify({
        provider,
        scope: 'organization',
        credentials: { api_key: apiKey },
        label: provider,
      }),
    });
    setApiKey('');
    load();
  }

  return (
    <motion>
      <PageHeader
        title="Integraciones"
        description="Conexiones a proveedores (IA, email, WhatsApp…). Se configuran una vez y las apps las reutilizan."
      />
      <form onSubmit={create} className="card mb-6 flex flex-wrap gap-3">
        <select value={provider} onChange={(e) => setProvider(e.target.value)}>
          <option value="gemini">Google Gemini</option>
          <option value="email">Email</option>
          <option value="whatsapp">Meta WhatsApp</option>
        </select>
        <input
          className="min-w-[200px] flex-1"
          placeholder="API key o credencial"
          value={apiKey}
          onChange={(e) => setApiKey(e.target.value)}
          required
        />
        <button type="submit" className="btn">
          Añadir (nivel organización)
        </button>
      </form>
      <div className="space-y-2">
        {list.map((c) => (
          <div key={c.id} className="card flex items-center justify-between py-4">
            <div>
              <p className="font-medium text-slate-900">{c.label}</p>
              <p className="text-xs text-slate-500">{c.provider} · {c.scope}</p>
